#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {
TOTAL_STAGES=8

# Usage: infra/auth-setup.sh [dev|prod]   (default dev). Run from anywhere.
ENV_NAME="${1:-dev}"
[[ "$ENV_NAME" == dev || "$ENV_NAME" == prod ]] || { echo "usage: $0 [dev|prod]" >&2; exit 2; }
ROOT=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
TF_DIR="$ROOT/infra/terraform/envs/$ENV_NAME"
TFVARS="$TF_DIR/terraform.tfvars"
PROJECT=$(sed -nE 's/^project_id[[:space:]]*=[[:space:]]*"([^"]+)".*/\1/p' "$TFVARS")
ANDROID_JSON="$ROOT/app/android/app/google-services.json"
IOS_PLIST="$ROOT/app/ios/Runner/GoogleService-Info.plist"
INFO_PLIST="$ROOT/app/ios/Runner/Info.plist"
PB=/usr/libexec/PlistBuddy
tf() { terraform -chdir="$TF_DIR" "$@"; }

# upsert_tfvar NAME VALUE: set NAME = VALUE (raw HCL) in terraform.tfvars.
upsert_tfvar() {
  local name="$1" value="$2" tmp
  tmp=$(mktemp)
  grep -vE "^${name}[[:space:]]*=" "$TFVARS" > "$tmp" || true
  printf '%s = %s\n' "$name" "$value" >> "$tmp"
  mv "$tmp" "$TFVARS"
}

banner "Cesta sign-in setup ($ENV_NAME: $PROJECT)"

stage "Check tools"
say "This sets up Firebase Authentication for $PROJECT and wires the app to it."
missing=()
for cmd in gcloud terraform keytool base64; do command -v "$cmd" >/dev/null || missing+=("$cmd"); done
[[ -x "$PB" ]] || missing+=("PlistBuddy (macOS)")
if (( ${#missing[@]} )); then
  warn "Missing: ${missing[*]}. Install them and run this again."
  exit 1
fi
step "All tools found. Terraform must be able to reach the $ENV_NAME state (infra/README.md)."
note "If you haven't yet: gcloud auth application-default login"
tf init -backend-config=backend.hcl -input=false >/dev/null
pause

stage "Adopt anything already made in the Firebase console"
say "Terraform now manages the sign-in config and the Android and iOS apps."
say "Anything already created by hand has to be imported first, or apply fails with 'already exists'."
open_url "https://console.firebase.google.com/project/$PROJECT/settings/general"
if confirm "Did you already enable a sign-in method in Authentication (e.g. Email/Password)?"; then
  tf import module.environment.google_identity_platform_config.auth "projects/$PROJECT/config" || warn "import failed; check above"
fi
if confirm "Is an Android app (dev.tsantana.cesta) already listed under 'Your apps'?"; then
  step "Click the Android app and copy its App ID (looks like 1:1234567890:android:abc123)."
  ask ANDROID_APP_ID "Android App ID:"
  tf import module.environment.google_firebase_android_app.cesta "projects/$PROJECT/androidApps/$ANDROID_APP_ID" || warn "import failed; check above"
fi
if confirm "Is an iOS app (dev.tsantana.cesta) already listed under 'Your apps'?"; then
  step "Click the iOS app and copy its App ID (looks like 1:1234567890:ios:abc123)."
  ask IOS_APP_ID "iOS App ID:"
  tf import module.environment.google_firebase_apple_app.cesta "projects/$PROJECT/iosApps/$IOS_APP_ID" || warn "import failed; check above"
fi

stage "Register the Android signing key"
say "Google sign-in on Android only works for builds signed with a registered key."
say "We'll read your debug keystore's fingerprints (public values) into $TFVARS."
KEYSTORE="${ANDROID_KEYSTORE:-$HOME/.android/debug.keystore}"
if [[ ! -f "$KEYSTORE" ]]; then
  warn "No keystore at $KEYSTORE. Build the Android app once (flutter run) to create it, then run this again."
  warn "For a release key, run with ANDROID_KEYSTORE=/path/to/key.jks (the password prompt comes from keytool)."
  exit 1
fi
if [[ "$KEYSTORE" == "$HOME/.android/debug.keystore" ]]; then
  certs=$(keytool -list -v -keystore "$KEYSTORE" -alias androiddebugkey -storepass android -keypass android)
else
  certs=$(keytool -list -v -keystore "$KEYSTORE")
fi
sha1=$(printf '%s\n' "$certs" | sed -nE 's/^[[:space:]]*SHA1:[[:space:]]*//p' | head -1 | tr -d ':' | tr 'A-F' 'a-f')
sha256=$(printf '%s\n' "$certs" | sed -nE 's/^[[:space:]]*SHA256:[[:space:]]*//p' | head -1 | tr -d ':' | tr 'A-F' 'a-f')
[[ -n "$sha1" && -n "$sha256" ]] || { warn "Couldn't read fingerprints from keytool output."; exit 1; }
step "SHA-1:   $sha1"
step "SHA-256: $sha256"
note "Several machines or a release key? Edit the lists in $TFVARS by hand afterwards."
if confirm "Write these to $TFVARS (replacing what's there)?"; then
  upsert_tfvar android_sha1_hashes "[\"$sha1\"]"
  upsert_tfvar android_sha256_hashes "[\"$sha256\"]"
else
  SKIPPED+=("android_sha1_hashes / android_sha256_hashes in $TFVARS")
fi

stage "Apply Terraform"
say "This turns on Email/Password sign-in, registers the apps and points the backend at"
say "Firebase project $PROJECT (FIREBASE_PROJECT_ID, TRUSTED_PROXY_HOPS)."
warn "It upgrades $PROJECT to Firebase Authentication with Identity Platform. That can't be undone,"
warn "but it's free up to 50,000 monthly active users for email and Google sign-in."
tf plan -input=false -out=auth.tfplan
if confirm "Apply this plan?"; then
  tf apply -input=false auth.tfplan
else
  SKIPPED+=("terraform apply in $TF_DIR")
fi
rm -f "$TF_DIR/auth.tfplan"

stage "Firebase console: enable Google sign-in"
say "Terraform can't create the Google OAuth client, but the console does it for you."
open_url "https://console.firebase.google.com/project/$PROJECT/authentication/providers"
step "Under Sign-in providers, click 'Add new provider' (or 'Google' if listed) → Google."
step "Toggle Enable, choose your email as the project support email, click Save."
step "Check that Email/Password shows as Enabled too."
pause "Press Enter once Google shows as Enabled"

stage "Write the app's Firebase config files"
say "Enabling Google added OAuth clients to the app config, so we refresh Terraform's view first."
tf apply -refresh-only -input=false -auto-approve >/dev/null
tf output -raw android_config_file | base64 --decode > "$ANDROID_JSON"
tf output -raw apple_config_file | base64 --decode > "$IOS_PLIST"
step "Wrote ${ANDROID_JSON#"$ROOT"/}"
step "Wrote ${IOS_PLIST#"$ROOT"/}"
if ! grep -q '"client_type": 3' "$ANDROID_JSON"; then
  warn "google-services.json has no web OAuth client yet, so Google sign-in won't work on Android."
  warn "Wait a minute after enabling Google and run this wizard again."
  SKIPPED+=("re-run once google-services.json has a web client (client_type 3)")
fi
note "These are public client identifiers, not secrets: commit them."
pause

stage "iOS: URL scheme and Xcode target"
REVERSED=$("$PB" -c 'Print :REVERSED_CLIENT_ID' "$IOS_PLIST" 2>/dev/null || true)
CLIENT_ID=$("$PB" -c 'Print :CLIENT_ID' "$IOS_PLIST" 2>/dev/null || true)
if [[ -z "$REVERSED" || -z "$CLIENT_ID" ]]; then
  warn "GoogleService-Info.plist has no CLIENT_ID yet (Google not enabled when it was fetched). Re-run this wizard."
  SKIPPED+=("iOS URL scheme (REVERSED_CLIENT_ID)")
else
  "$PB" -c 'Delete :CFBundleURLTypes' "$INFO_PLIST" 2>/dev/null || true
  "$PB" -c 'Add :CFBundleURLTypes array' \
        -c 'Add :CFBundleURLTypes:0 dict' \
        -c 'Add :CFBundleURLTypes:0:CFBundleTypeRole string Editor' \
        -c 'Add :CFBundleURLTypes:0:CFBundleURLSchemes array' \
        -c "Add :CFBundleURLTypes:0:CFBundleURLSchemes:0 string $REVERSED" "$INFO_PLIST"
  "$PB" -c 'Delete :GIDClientID' "$INFO_PLIST" 2>/dev/null || true
  "$PB" -c "Add :GIDClientID string $CLIENT_ID" "$INFO_PLIST"
  step "Info.plist: Google sign-in URL scheme and GIDClientID set."
fi
say "The plist must be part of the Runner target, which only Xcode can do safely:"
open_url "$ROOT/app/ios/Runner.xcworkspace"
step "In the Project navigator, right-click the Runner folder → 'Add Files to \"Runner\"…'."
step "Pick app/ios/Runner/GoogleService-Info.plist. Leave 'Copy items if needed' off, tick target Runner, click Add."
pause "Press Enter once the file shows in Runner"

stage "Try it"
say "Sign in once with each method against the local backend (it accepts tokens from cesta-dev):"
step "Terminal 1: cd backend && make dev"
step "Terminal 2: cd app && flutter run   (Android emulator: --dart-define=API_BASE_URL=http://10.0.2.2:8080)"
step "Create an account with email + password, confirm the name, sign out."
step "Continue with Google, sign out. Forgot password? → check the email arrives."
note "After the next deploy, check per-IP rate limiting sees real client addresses: if users"
note "get 429s together, TRUSTED_PROXY_HOPS in infra/terraform/modules/environment/run.tf is wrong."
pause "Press Enter when done"

finish
}

run_wizard "$@"; exit
